local PkgImage = require("pkg_image")
local B,W=15,0
local pages={"月报","品类","记录","AI总结"}
local function header(g,s) g:clear(W); PkgImage.draw(g, "brand_logo", 24, 18); g:text(356,32,"8月账单",{color=B}); g:line(24,78,456,78,{color=B}); local x=24; for i,v in ipairs(pages) do g:text(x+16,102,v,{color=B}); if s.page==i then g:line(x+10,132,x+78,132,{color=B}); g:line(x+10,135,x+78,135,{color=B}) end; x=x+108 end end
local function overview(g,s) header(g,s); PkgImage.draw(g, "feature_scene", 120, 146); g:text(24,318,"本月美食消费",{color=B}); g:text(24,362,"¥1,337.3",{color=B}); g:line(24,404,456,404,{color=B}); g:text(24,430,"24 单",{color=B}); g:text(170,430,"平均每单 55.7",{color=B}); g:text(356,430,"外卖 20",{color=B}); g:line(24,466,456,466,{color=B}); g:text(24,486,"一日三餐",{color=B}); local bars={{"早餐",4,100},{"午餐",8,200},{"晚餐",8,200},{"夜宵",4,100}}; for i,v in ipairs(bars) do local y=526+(i-1)*42; g:text(24,y,v[1],{color=B}); g:rect(104,y+8,v[3],7,{fill=true,color=B}); g:text(330,y,v[2].." 次",{color=B}) end; g:line(24,696,456,696,{color=B}); g:text(24,720,"关键词",{color=B}); g:text(146,720,"工作餐 · 咖啡 · 周末聚餐",{color=B}) end
local function category(g,s) header(g,s); g:text(24,158,"吃得最多",{color=B}); local rows={{"icon_hotpot","川湘菜","6单 · ¥328.6"},{"icon_sushi","日料寿司","5单 · ¥302.0"},{"icon_salad","轻食沙拉","5单 · ¥190.7"},{"icon_bbq","烧烤聚餐","4单 · ¥310.0"}}; for i,v in ipairs(rows) do local y=204+(i-1)*126; PkgImage.draw(g, v[1], 24, y); g:text(88,y+4,v[2],{color=B}); g:text(88,y+40,v[3],{color=B}); g:line(88,y+76,456,y+76,{color=B}); if i==1 then g:rect(88,y-2,5,66,{fill=true,color=B}) end end; g:text(24,718,"咖啡与饮品 4 单 · ¥206.0",{color=B}) end
local function records(g,s) header(g,s); g:text(24,158,"观澜湖消费",{color=B}); local rows={{"icon_bowl","08-25  湖畔轻食","¥37.8"},{"icon_coffee","08-24  太二观澜湖店","¥58.0"},{"icon_sushi","08-23  观澜湖七分甜","¥22.0"},{"icon_hotpot","08-22  炙味观澜湖店","¥88.0"},{"icon_salad","08-21  运动公社轻食","¥43.0"}}; for i,v in ipairs(rows) do local y=202+(i-1)*104; PkgImage.draw(g, v[1], 24, y); g:text(88,y+4,v[2],{color=B}); g:text(366,y+4,v[3],{color=B}); g:text(88,y+40,i==1 and "外卖 · 轻食" or "观澜湖 · 美食",{color=B}); g:line(88,y+76,456,y+76,{color=B}) end end
local function ai(g,s) header(g,s); PkgImage.draw(g, "icon_ai", 24, 158); g:text(88,166,"LongCat 月度洞察",{color=B}); g:line(88,202,456,202,{color=B}); PkgImage.draw(g, "feature_scene", 120, 232); local lines={"这个月你花了 1,337.3 元吃饭，","工作日午餐最稳定，川湘菜出现最多。","咖啡多集中在早晨，周末更偏向聚餐。","","4 次夜宵都在 21:00 以后，","下个月可以把其中两次换成轻食，","预算控制在 1,200 元会更舒服。"}; for i,v in ipairs(lines) do g:text(24,410+(i-1)*38,v,{color=B}) end end
function on_load(ctx) if not ctx.state.food then ctx.state.food={page=1} end; ctx:set_tick(0) end
function on_draw(ctx,g) require("pkg_image").bind(ctx); local s=ctx.state.food; if s.page==1 then overview(g,s) elseif s.page==2 then category(g,s) elseif s.page==3 then records(g,s) else ai(g,s) end end
function on_input(ctx,ev) if not (ev.type == "pointer" and ev.phase == "up") then return false end; local s=ctx.state.food; if ev.gesture=="swipe_left" then s.page=s.page%4+1 elseif ev.gesture=="swipe_right" then s.page=(s.page+2)%4+1 elseif ev.gesture=="tap" and ev.y>=88 and ev.y<=140 then s.page=math.max(1,math.min(4,math.floor((ev.x-24)/108)+1)) else return false end; ctx:invalidate(); return true end
